/// The bytes Shift_JIS spells one character with. None where it has none.
pub(crate) fn shift_jis_bytes_for(character: char) -> Option<Vec<u8>> {
    let point = character as u32;
    if point < 0x80 {
        return Some(vec![point as u8]);
    }
    let at = SHIFT_JIS_CHARACTERS
        .binary_search_by_key(&point, |(held, _)| *held)
        .ok()?;
    let packed = SHIFT_JIS_CHARACTERS[at].1;
    if packed > 0xff {
        return Some(vec![(packed >> 8) as u8, (packed & 0xff) as u8]);
    }
    Some(vec![packed as u8])
}

/// The character a run of Shift_JIS bytes spells, alongside how many bytes it
/// took. None where the run opens no character the encoding names.
pub(crate) fn shift_jis_character(bytes: &[u8]) -> Option<(char, usize)> {
    let first = *bytes.first()?;
    if first < 0x80 {
        return Some((char::from(first), 1));
    }
    let width = if (0x81..=0x9f).contains(&first) || (0xe0..=0xfc).contains(&first) {
        2
    } else {
        1
    };
    if bytes.len() < width {
        return None;
    }
    let mut packed = 0u32;
    for byte in &bytes[..width] {
        packed = (packed << 8) | *byte as u32;
    }
    let at = SHIFT_JIS_CHARACTERS
        .iter()
        .position(|(_, held)| *held == packed)?;
    char::from_u32(SHIFT_JIS_CHARACTERS[at].0).map(|held| (held, width))
}

/// The bytes Shift_JIS spells a whole text with, or the first character it
/// has no bytes for.
pub(crate) fn shift_jis_bytes(text: &str) -> Result<Vec<u8>, char> {
    let mut bytes = Vec::with_capacity(text.len());
    for character in text.chars() {
        match shift_jis_bytes_for(character) {
            Some(spelled) => bytes.extend(spelled),
            None => return Err(character),
        }
    }
    Ok(bytes)
}

/// The text a run of Shift_JIS bytes spells. A byte the encoding does not open
/// a character with stands for itself.
pub(crate) fn shift_jis_text(bytes: &[u8]) -> String {
    let mut written = String::with_capacity(bytes.len());
    let mut at = 0usize;
    while at < bytes.len() {
        match shift_jis_character(&bytes[at..]) {
            Some((character, width)) => {
                written.push(character);
                at += width;
            }
            None => {
                written.push(char::from(bytes[at]));
                at += 1;
            }
        }
    }
    written
}
